import json,urllib.request
base="http://127.0.0.1:17448/api/supervisor-watchdog"
out={}
try:
 with urllib.request.urlopen(base,timeout=6) as r:j=json.loads(r.read(200000).decode("utf8"))
 for group in ("config","capabilities","runtime","detection"):
  v=j.get(group)
  if not isinstance(v,dict):
   out[group]={"type":type(v).__name__}
   continue
  safe={}
  for k,x in v.items():
   if isinstance(x,(bool,int,float)) or x is None:safe[k]=x
   elif isinstance(x,str) and len(x)<90 and not any(q in k.lower() for q in ("error","url","token","secret","prompt","message","text","id")):safe[k]=x
   elif isinstance(x,dict):
    safe[k]={"keys":list(x.keys())[:28]}
   elif isinstance(x,list):safe[k]={"count":len(x)}
  out[group]={"keys":list(v.keys())[:50],"safe":safe}
except Exception as e:out={"error_type":type(e).__name__}
print(json.dumps(out,ensure_ascii=True))
